def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Extend a diagonal pair only if its two other 2x2 corners are background.
    for r in range(h - 1):
        for c in range(w - 1):
            for dc in (-1, 1):
                c2 = c + dc
                if not (0 <= c2 < w):
                    continue
                color = grid[r][c]
                if color == bg or grid[r + 1][c2] != color:
                    continue
                other1, other2 = c + dc, c
                if grid[r][other1] != bg or grid[r + 1][other2] != bg:
                    continue

                # Continue the diagonal outward from each end of the pair.
                for sr, sc in ((-1, -dc), (1, dc)):
                    rr, cc = r, c
                    while 0 <= rr + sr < h and 0 <= cc + sc < w:
                        rr += sr
                        cc += sc
                        if grid[rr][cc] != bg:
                            break
                        out[rr][cc] = color
    return out
